func testVeiculoToManyAddOpVeiCarregamentos(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Veiculo
	var b, c, d, e Carregamento

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, veiculoDBTypes, false, strmangle.SetComplement(veiculoPrimaryKeyColumns, veiculoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*Carregamento{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, carregamentoDBTypes, false, strmangle.SetComplement(carregamentoPrimaryKeyColumns, carregamentoColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*Carregamento{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddVeiCarregamentos(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if !queries.Equal(a.VeiID, first.VeiID) {
			t.Error("foreign key was wrong value", a.VeiID, first.VeiID)
		}
		if !queries.Equal(a.VeiID, second.VeiID) {
			t.Error("foreign key was wrong value", a.VeiID, second.VeiID)
		}

		if first.R.Vei != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.Vei != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.VeiCarregamentos[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.VeiCarregamentos[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.VeiCarregamentos().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}

func testVeiculoToManySetOpVeiCarregamentos(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Veiculo
	var b, c, d, e Carregamento

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, veiculoDBTypes, false, strmangle.SetComplement(veiculoPrimaryKeyColumns, veiculoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*Carregamento{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, carregamentoDBTypes, false, strmangle.SetComplement(carregamentoPrimaryKeyColumns, carregamentoColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err = a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	err = a.SetVeiCarregamentos(ctx, tx, false, &b, &c)
	if err != nil {
		t.Fatal(err)
	}

	count, err := a.VeiCarregamentos().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	err = a.SetVeiCarregamentos(ctx, tx, true, &d, &e)
	if err != nil {
		t.Fatal(err)
	}

	count, err = a.VeiCarregamentos().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	if !queries.IsValuerNil(b.VeiID) {
		t.Error("want b's foreign key value to be nil")
	}
	if !queries.IsValuerNil(c.VeiID) {
		t.Error("want c's foreign key value to be nil")
	}
	if !queries.Equal(a.VeiID, d.VeiID) {
		t.Error("foreign key was wrong value", a.VeiID, d.VeiID)
	}
	if !queries.Equal(a.VeiID, e.VeiID) {
		t.Error("foreign key was wrong value", a.VeiID, e.VeiID)
	}

	if b.R.Vei != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if c.R.Vei != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if d.R.Vei != &a {
		t.Error("relationship was not added properly to the foreign struct")
	}
	if e.R.Vei != &a {
		t.Error("relationship was not added properly to the foreign struct")
	}

	if a.R.VeiCarregamentos[0] != &d {
		t.Error("relationship struct slice not set to correct value")
	}
	if a.R.VeiCarregamentos[1] != &e {
		t.Error("relationship struct slice not set to correct value")
	}
}

func testVeiculoToManyRemoveOpVeiCarregamentos(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Veiculo
	var b, c, d, e Carregamento

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, veiculoDBTypes, false, strmangle.SetComplement(veiculoPrimaryKeyColumns, veiculoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*Carregamento{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, carregamentoDBTypes, false, strmangle.SetComplement(carregamentoPrimaryKeyColumns, carregamentoColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	err = a.AddVeiCarregamentos(ctx, tx, true, foreigners...)
	if err != nil {
		t.Fatal(err)
	}

	count, err := a.VeiCarregamentos().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 4 {
		t.Error("count was wrong:", count)
	}

	err = a.RemoveVeiCarregamentos(ctx, tx, foreigners[:2]...)
	if err != nil {
		t.Fatal(err)
	}

	count, err = a.VeiCarregamentos().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	if !queries.IsValuerNil(b.VeiID) {
		t.Error("want b's foreign key value to be nil")
	}
	if !queries.IsValuerNil(c.VeiID) {
		t.Error("want c's foreign key value to be nil")
	}

	if b.R.Vei != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if c.R.Vei != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if d.R.Vei != &a {
		t.Error("relationship to a should have been preserved")
	}
	if e.R.Vei != &a {
		t.Error("relationship to a should have been preserved")
	}

	if len(a.R.VeiCarregamentos) != 2 {
		t.Error("should have preserved two relationships")
	}

	// Removal doesn't do a stable deletion for performance so we have to flip the order
	if a.R.VeiCarregamentos[1] != &d {
		t.Error("relationship to d should have been preserved")
	}
	if a.R.VeiCarregamentos[0] != &e {
		t.Error("relationship to e should have been preserved")
	}
}

