func testVeiculoToOneEmpresaFilialUsingEmf(t *testing.T) {
	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var local Veiculo
	var foreign EmpresaFilial

	seed := randomize.NewSeed()
	if err := randomize.Struct(seed, &local, veiculoDBTypes, false, veiculoColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize Veiculo struct: %s", err)
	}
	if err := randomize.Struct(seed, &foreign, empresaFilialDBTypes, false, empresaFilialColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize EmpresaFilial struct: %s", err)
	}

	if err := foreign.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	local.EmfID = foreign.EmfID
	if err := local.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	check, err := local.Emf().One(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}

	if check.EmfID != foreign.EmfID {
		t.Errorf("want: %v, got %v", foreign.EmfID, check.EmfID)
	}

	ranAfterSelectHook := false
	AddEmpresaFilialHook(boil.AfterSelectHook, func(ctx context.Context, e boil.ContextExecutor, o *EmpresaFilial) error {
		ranAfterSelectHook = true
		return nil
	})

	slice := VeiculoSlice{&local}
	if err = local.L.LoadEmf(ctx, tx, false, (*[]*Veiculo)(&slice), nil); err != nil {
		t.Fatal(err)
	}
	if local.R.Emf == nil {
		t.Error("struct should have been eager loaded")
	}

	local.R.Emf = nil
	if err = local.L.LoadEmf(ctx, tx, true, &local, nil); err != nil {
		t.Fatal(err)
	}
	if local.R.Emf == nil {
		t.Error("struct should have been eager loaded")
	}

	if !ranAfterSelectHook {
		t.Error("failed to run AfterSelect hook for relationship")
	}
}

func testVeiculoToOneSetOpEmpresaFilialUsingEmf(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Veiculo
	var b, c EmpresaFilial

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, veiculoDBTypes, false, strmangle.SetComplement(veiculoPrimaryKeyColumns, veiculoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &b, empresaFilialDBTypes, false, strmangle.SetComplement(empresaFilialPrimaryKeyColumns, empresaFilialColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &c, empresaFilialDBTypes, false, strmangle.SetComplement(empresaFilialPrimaryKeyColumns, empresaFilialColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	for i, x := range []*EmpresaFilial{&b, &c} {
		err = a.SetEmf(ctx, tx, i != 0, x)
		if err != nil {
			t.Fatal(err)
		}

		if a.R.Emf != x {
			t.Error("relationship struct not set to correct value")
		}

		if x.R.EmfVeiculos[0] != &a {
			t.Error("failed to append to foreign relationship struct")
		}
		if a.EmfID != x.EmfID {
			t.Error("foreign key was wrong value", a.EmfID)
		}

		zero := reflect.Zero(reflect.TypeOf(a.EmfID))
		reflect.Indirect(reflect.ValueOf(&a.EmfID)).Set(zero)

		if err = a.Reload(ctx, tx); err != nil {
			t.Fatal("failed to reload", err)
		}

		if a.EmfID != x.EmfID {
			t.Error("foreign key was wrong value", a.EmfID, x.EmfID)
		}
	}
}

